"""Custom exception hierarchy for the ISO 26262 ARXML Parser toolchain.

This module defines specific error classes used across the parsing, validation,
and reporting pipeline to handle structural deviations and infrastructure faults.
"""

class ARXMLToolError(Exception):
    """Base exception class for all errors generated by this tool.

    All specialized exceptions in this package inherit from this class to allow
    a single, high-level catch block in execution scripts.
    """
    pass

class ARXMLValidationError(ARXMLToolError):
    """Raised when the ARXML content violates schema or structural rules.

    This includes missing mandatory AUTOSAR elements, illegal cross-references,
    or failures during the functional safety compliance checks.
    """
    pass

class ARXMLFileNotFoundError(ARXMLValidationError):
    """Raised when the specified input ARXML file path does not exist.

    This prevents downstream parsing steps from executing with invalid or
    missing file system contexts.
    """
    pass

class ARXMLParserError(ARXMLToolError):
    """Raised when the underlying XML parser fails to read the file.

    Typically triggered by malformed XML syntax, corrupt files, or unsupported
    encoding schemes that break the lxml tree generation.
    """
    pass